#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    if (n >= 4 && m >= 4) {
        cout << n * m - ((n * m) % 2) << endl;
    } else {
        int min_nm = min(n, m);
        int max_nm = max(n, m);
        if (min_nm == 1) {
            int rem = max_nm % 6;
            int base = (max_nm / 6) * 6;
            if (rem == 5) {
                cout << base + 4 << endl;
            } else if (rem == 4) {
                cout << base + 2 << endl;
            } else {
                cout << base << endl;
            }
        } else if (min_nm == 2 && max_nm == 7) {
            cout << 12 << endl;
        } else if ((min_nm == 2 && max_nm >= 4) || (min_nm == 3 && max_nm >= 4)) {
            cout << n * m - ((n * m) % 2) << endl;
        } else {
            int pattern[5][5] = {
                {0, 0, 0, 2, 4},
                {0, 0, 4, 8, 10},
                {0, 0, 8, 12, 14},
                {0, 0, 0, 16, 20},
                {0, 0, 0, 0, 24}
            };
            cout << pattern[min_nm - 1][max_nm - 1] << endl;
        }
    }
    return 0;
}
